import React, { useState } from 'react';
import { Radio, Thermometer, Activity, Zap, Gauge, Filter, Search, RefreshCw, CheckCircle2 } from 'lucide-react';

const SensorMonitoringPage = () => {
  const [filterType, setFilterType] = useState('All');
  const [search, setSearch] = useState('');

  const sensors = [
    { id: 'SNS-TEMP-101', name: 'Main Drive Motor Thermocouple', loom: 'LOOM-101', type: 'Temperature', val: '52.4 °C', status: 'Normal', update: '1s ago' },
    { id: 'SNS-VIB-101', name: 'Shedding Motion Transducer', loom: 'LOOM-101', type: 'Vibration', val: '0.18 mm/s', status: 'Normal', update: '1s ago' },
    { id: 'SNS-RPM-101', name: 'Main Shaft Optical Tachometer', loom: 'LOOM-101', type: 'RPM', val: '1,080 RPM', status: 'Normal', update: '1s ago' },
    { id: 'SNS-TENS-101', name: 'Weft Insertion Tension Sensor', loom: 'LOOM-101', type: 'Tension', val: '18.2 cN', status: 'Normal', update: '1s ago' },
    { id: 'SNS-TEMP-201', name: 'Bearing Thermal Sensor', loom: 'LOOM-201', type: 'Temperature', val: '76.8 °C', status: 'Warning', update: '1s ago' },
    { id: 'SNS-VIB-201', name: 'Drive Shaft Accelerometer', loom: 'LOOM-201', type: 'Vibration', val: '0.42 mm/s', status: 'Critical', update: '1s ago' },
    { id: 'SNS-AIR-301', name: 'Air Jet Nozzle Pressure Sensor', loom: 'LOOM-301', type: 'Air Pressure', val: '6.2 Bar', status: 'Normal', update: '1s ago' },
    { id: 'SNS-PWR-501', name: 'Digital Power Meter', loom: 'LOOM-501', type: 'Power', val: '16.4 kW', status: 'Normal', update: '1s ago' },
  ];

  const filteredSensors = sensors.filter((s) => {
    const matchType = filterType === 'All' || s.type === filterType;
    const matchSearch = s.name.toLowerCase().includes(search.toLowerCase()) || s.loom.toLowerCase().includes(search.toLowerCase());
    return matchType && matchSearch;
  });

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>📡 Live IoT Sensor Telemetry Monitor</h1>
            <span className="badge badge-running" style={{ fontWeight: '800' }}>136 IoT Feeds Online</span>
          </div>
          <p>Continuous Real-Time Telemetry Stream for Temperature, Vibration, Tachometers, and Yarn Tension</p>
        </div>

        <button className="btn btn-primary" onClick={() => alert('Refreshing IoT sensor feeds...')}>
          <RefreshCw size={16} /> Poll Telemetry Stream
        </button>
      </div>

      {/* Controls */}
      <div className="glass-card" style={{ padding: '1rem 1.25rem', marginBottom: '1.5rem', display: 'flex', gap: '1rem', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          {['All', 'Temperature', 'Vibration', 'RPM', 'Tension', 'Air Pressure', 'Power'].map((t) => (
            <button
              key={t}
              onClick={() => setFilterType(t)}
              className={`btn ${filterType === t ? 'btn-primary' : 'btn-secondary'}`}
              style={{ fontSize: '0.8rem', padding: '0.4rem 0.8rem' }}
            >
              {t}
            </button>
          ))}
        </div>

        <div style={{ position: 'relative', minWidth: '240px' }}>
          <Search size={14} style={{ position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
          <input
            type="text"
            className="form-control"
            style={{ paddingLeft: '2.2rem', height: '36px', fontSize: '0.85rem' }}
            placeholder="Search sensor ID or Loom..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* Sensor Feeds Table */}
      <div className="glass-card" style={{ padding: '1.25rem' }}>
        <div className="table-responsive">
          <table className="custom-table">
            <thead>
              <tr>
                <th>Sensor ID</th>
                <th>Sensor Name</th>
                <th>Target Loom</th>
                <th>Sensor Type</th>
                <th>Live Value</th>
                <th>Status</th>
                <th>Last Update</th>
              </tr>
            </thead>
            <tbody>
              {filteredSensors.map((s) => (
                <tr key={s.id}>
                  <td style={{ fontFamily: 'JetBrains Mono', color: 'var(--accent-primary)', fontWeight: '800' }}>{s.id}</td>
                  <td style={{ fontWeight: '800' }}>{s.name}</td>
                  <td style={{ fontFamily: 'JetBrains Mono', fontWeight: '800' }}>{s.loom}</td>
                  <td><span className="badge badge-low">{s.type}</span></td>
                  <td style={{ fontWeight: '900', fontSize: '0.95rem' }}>{s.val}</td>
                  <td>
                    <span className={`badge badge-${s.status === 'Normal' ? 'running' : s.status === 'Warning' ? 'idle' : 'maintenance'}`}>
                      {s.status}
                    </span>
                  </td>
                  <td style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>{s.update}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default SensorMonitoringPage;
